import pandas as pd
import re
import random


def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    columns = ["ID", "Quantity", "Code", "Price", "Product", "Description"]
    product_names = ["Apple", "Banana", "Orange", "Pear", "Grape"]

    random.seed(seed)
    code_to_product = {}
    rows = []

    if not s or not s.strip():
        return pd.DataFrame(columns=columns)

    for line in s.splitlines():
        line = line.rstrip()
        if not line.strip():
            continue

        parts = re.split(r"\s+", line.strip(), maxsplit=4)
        if len(parts) < 5:
            continue

        product_id, quantity, code, price, description = parts

        try:
            quantity = int(quantity)
            price = int(price)
        except ValueError:
            continue

